input.command:
curl -sL "https://www.ganjingworld.com/article/1h2hvr7vnil5CRdZgIX5tk5zF1ht1c" -H "User-Agent: Mozilla/5.0" 2>/dev/null | python3 -c "
import sys, json, re
html = sys.stdin.read()
m = re.search(r'__NEXT_DATA__[^>]*>(.*?)</script>', html)
if m:
    d = json.loads(m.group(1))
    pp = d.get('props',{}).get('pageProps',{})
    art = pp.get('article') or pp.get('post') or pp
    for k in ['title','content','body','text','description','publishedAt','createdAt']:
        if k in art:
            val = str(art[k])[:800]
            print(f'{k}: {val}')
    if 'article' not in pp and 'post' not in pp:
        for k,v in pp.items():
            if isinstance(v, dict) and ('title' in v or 'content' in v or 'body' in v):
                print(f'FOUND in {k}:')
                for sk in ['title','content','body','text']:
                    if sk in v: print(f'  {sk}: {str(v[sk])[:500]}')
" 2>/dev/null || echo "parse failed"

